// layout-settings-provider and font-provider exported via @masan-group/shared-ui/layout
export { LayoutSettingsProvider, useLayoutSettings } from './layout-settings-provider';
export type {
  Collapsible as SidebarCollapsible,
  Variant as SidebarVariant,
} from './layout-settings-provider';
export { FontProvider, useFont } from './font-provider';

import { createContext, useContext, useEffect, useState } from 'react';
import { getCookie, setCookie } from '../lib/cookies';

export type Collapsible = 'offcanvas' | 'icon' | 'none';
export type Variant = 'inset' | 'sidebar' | 'floating';

const LAYOUT_COLLAPSIBLE_COOKIE_NAME = 'layout_collapsible';
const LAYOUT_VARIANT_COOKIE_NAME = 'layout_variant';
const LAYOUT_FONT_SIZE_COOKIE_NAME = 'layout_font_size';
const LAYOUT_COOKIE_MAX_AGE = 60 * 60 * 24 * 7; // 7 days

const DEFAULT_VARIANT: Variant = 'inset';
const DEFAULT_COLLAPSIBLE: Collapsible = 'icon';
const DEFAULT_FONT_SIZE = 12;

type LayoutSettingsContextType = {
  resetLayout: () => void;

  defaultCollapsible: Collapsible;
  collapsible: Collapsible;
  setCollapsible: (collapsible: Collapsible) => void;

  defaultVariant: Variant;
  variant: Variant;
  setVariant: (variant: Variant) => void;

  defaultFontSize: number;
  fontSize: number;
  setFontSize: (size: number) => void;
};

const LayoutSettingsContext = createContext<LayoutSettingsContextType | null>(null);

type LayoutSettingsProviderProps = {
  children: React.ReactNode;
};

export function LayoutSettingsProvider({ children }: LayoutSettingsProviderProps) {
  const [collapsible, _setCollapsible] = useState<Collapsible>(() => {
    const saved = getCookie(LAYOUT_COLLAPSIBLE_COOKIE_NAME);
    return (saved as Collapsible) || DEFAULT_COLLAPSIBLE;
  });

  const [variant, _setVariant] = useState<Variant>(() => {
    const saved = getCookie(LAYOUT_VARIANT_COOKIE_NAME);
    return (saved as Variant) || DEFAULT_VARIANT;
  });

  const [fontSize, _setFontSize] = useState<number>(() => {
    const saved = getCookie(LAYOUT_FONT_SIZE_COOKIE_NAME);
    return saved ? Number(saved) : DEFAULT_FONT_SIZE;
  });

  const setCollapsible = (newCollapsible: Collapsible) => {
    _setCollapsible(newCollapsible);
    setCookie(LAYOUT_COLLAPSIBLE_COOKIE_NAME, newCollapsible, {
      maxAge: LAYOUT_COOKIE_MAX_AGE,
    });
  };

  const setVariant = (newVariant: Variant) => {
    _setVariant(newVariant);
    setCookie(LAYOUT_VARIANT_COOKIE_NAME, newVariant, {
      maxAge: LAYOUT_COOKIE_MAX_AGE,
    });
  };

  const setFontSize = (newSize: number) => {
    const clampedSize = Math.min(18, Math.max(10, newSize));
    _setFontSize(clampedSize);
    setCookie(LAYOUT_FONT_SIZE_COOKIE_NAME, String(clampedSize), {
      maxAge: LAYOUT_COOKIE_MAX_AGE,
    });
    if (typeof document !== 'undefined') {
      document.documentElement.style.fontSize = `${clampedSize}px`;
    }
  };

  // Apply font-size on mount
  useEffect(() => {
    if (typeof document !== 'undefined') {
      document.documentElement.style.fontSize = `${fontSize}px`;
    }
  }, [fontSize]);

  const resetLayout = () => {
    setCollapsible(DEFAULT_COLLAPSIBLE);
    setVariant(DEFAULT_VARIANT);
    setFontSize(DEFAULT_FONT_SIZE);
  };

  const contextValue: LayoutSettingsContextType = {
    resetLayout,
    defaultCollapsible: DEFAULT_COLLAPSIBLE,
    collapsible,
    setCollapsible,
    defaultVariant: DEFAULT_VARIANT,
    variant,
    setVariant,
    defaultFontSize: DEFAULT_FONT_SIZE,
    fontSize,
    setFontSize,
  };

  return <LayoutSettingsContext value={contextValue}>{children}</LayoutSettingsContext>;
}

const NOOP = () => {};

/** Default values returned when no LayoutSettingsProvider is present */
const defaultSettings: LayoutSettingsContextType = {
  resetLayout: NOOP,
  defaultCollapsible: DEFAULT_COLLAPSIBLE,
  collapsible: DEFAULT_COLLAPSIBLE,
  setCollapsible: NOOP,
  defaultVariant: DEFAULT_VARIANT,
  variant: DEFAULT_VARIANT,
  setVariant: NOOP,
  defaultFontSize: DEFAULT_FONT_SIZE,
  fontSize: DEFAULT_FONT_SIZE,
  setFontSize: NOOP,
};

export function useLayoutSettings() {
  const context = useContext(LayoutSettingsContext);
  return context ?? defaultSettings;
}

import { createContext } from 'react';
import type { ModalContextType } from './type';

export const ModalContext = createContext<ModalContextType | null>(null);

export * from './context';
export * from './type';
export * from './useModals';
export * from './modals';

import { useState } from 'react';
import type React from 'react';
import { GlobalModal } from '../../components/patterns/modals/global-modal';
import { ModalContext } from './context';
import type { ModalConfig, ModalContextType } from './type';

// Store state setter for standalone functions (similar to Mantine pattern)
let setModalsState: React.Dispatch<React.SetStateAction<Record<string, ModalConfig>>> | null = null;

type ModalProviderProps = {
  children: React.ReactNode;
};

export function ModalProvider({ children }: ModalProviderProps) {
  const [modals, setModals] = useState<Record<string, ModalConfig>>({});

  const openModal = (config: ModalConfig) => {
    setModals((prev) => ({
      ...prev,
      [config.modalId]: config,
    }));
  };

  const closeModal = (id: string) => {
    setModals((prev) => {
      const { [id]: _, ...rest } = prev;
      return rest;
    });
  };

  const closeAllModals = () => {
    setModals({});
  };

  const updateModal = (id: string, updates: Partial<ModalConfig>) => {
    setModals((prev) => {
      if (!prev[id]) {
        return prev;
      }
      return {
        ...prev,
        [id]: {
          ...prev[id],
          ...updates,
        } as ModalConfig,
      };
    });
  };

  const contextValue: ModalContextType = {
    modals,
    openModal,
    closeModal,
    closeAllModals,
    updateModal,
  };

  // Store setter for standalone functions
  setModalsState = setModals;

  return (
    <ModalContext.Provider value={contextValue}>
      {children}
      <GlobalModal />
    </ModalContext.Provider>
  );
}

// Standalone functions (can be called from anywhere without hooks)
export function openModal(config: ModalConfig) {
  if (!setModalsState) {
    throw new Error('ModalProvider must be mounted before using openModal');
  }
  setModalsState((prev) => ({
    ...prev,
    [config?.modalId]: config,
  }));
}

export function closeModal(modalId: string) {
  if (!setModalsState) {
    throw new Error('ModalProvider must be mounted before using closeModal');
  }
  setModalsState((prev) => {
    const { [modalId]: _, ...rest } = prev;
    return rest;
  });
}

export function closeAllModals() {
  if (!setModalsState) {
    throw new Error('ModalProvider must be mounted before using closeAllModals');
  }
  setModalsState({});
}

export function updateModal(modalId: string, updates: Partial<ModalConfig>) {
  if (!setModalsState) {
    throw new Error('ModalProvider must be mounted before using updateModal');
  }
  setModalsState((prev) => {
    if (!prev[modalId]) {
      return prev;
    }
    return {
      ...prev,
      [modalId]: {
        ...prev[modalId],
        ...updates,
      } as ModalConfig,
    };
  });
}

// Helper functions for common modal types

/**
 * @description Helper functions for common modal types
 * @example
 * modals.close('my-modal');
 *
 * modals.closeAll();
 *
 * modals.updateProps('my-modal', { title: 'New Title' });
 *
 * modals.confirm({
 *   title: 'Are you sure?',
 *   onConfirm: () => console.log('confirmed'),
 * });
 *
 * modals.open({
 *   title: 'My Modal',
 *   content: <div>Content here</div>,
 * });
 *
 * modals.custom({
 *   component: MyCustomModal,
 *   componentProps: { title: 'Custom Modal' },
 *   onClose: () => console.log('closed'),
 * });
 */
export const modals = {
  close: closeModal,
  closeAll: closeAllModals,
  confirm: (
    config: Omit<
      Extract<ModalConfig, { type: 'confirm' | 'inner-content' }>,
      'type' | 'modalId' | 'style'
    > & { modalId?: string }
  ) => {
    openModal({
      ...config,
      type: 'confirm',
      style: 'dialog',
      modalId: config?.modalId || Date.now().toString(),
    } as ModalConfig);
  },
  open: (
    config: Omit<Extract<ModalConfig, { type: 'inner-content' }>, 'type' | 'modalId'> & {
      modalId?: string;
      style: 'dialog' | 'drawer';
    }
  ) => {
    openModal({
      ...config,
      type: 'inner-content',
      modalId: config?.modalId || Date.now().toString(),
    } as ModalConfig);
  },
  custom: <TProps = Record<string, unknown>>(
    config: Omit<
      Extract<ModalConfig, { type: 'custom' }>,
      'type' | 'modalId' | 'component' | 'componentProps'
    > & {
      modalId?: string;
      component: React.ComponentType<TProps>;
      componentProps?: TProps;
    }
  ) => {
    openModal({
      ...config,
      type: 'custom',
      modalId: config?.modalId || Date.now().toString(),
    } as ModalConfig);
  },
  updateProps: (modalId: string, updates: Partial<ModalConfig>) => {
    updateModal(modalId, updates);
  },
};

import type React from 'react';

type CustomModalConfig = {
  modalId: string;
  type: 'custom'; // full custom modal
  onClose?: () => void;
  onConfirm?: () => void | Promise<void>;
  // Modal component to be rendered
  component: React.ComponentType<Record<string, unknown>>;
  componentProps?: Record<string, unknown>;
};

export type ModalConfig =
  | CustomModalConfig
  | {
      modalId: string;
      type: 'confirm' | 'inner-content';
      style?: 'dialog' | 'drawer';
      direction?: 'top' | 'bottom' | 'left' | 'right';
      title?: React.ReactNode;
      description?: React.ReactNode;
      content?: React.ReactNode;
      variant?: 'default' | 'destructive' | 'success' | 'warning';
      onClose?: () => void;
      onConfirm?: () => void | Promise<void>;
      cancelText?: React.ReactNode;
      confirmText?: React.ReactNode;
      showCancel?: boolean;
      className?: string;
      hideFooter?: boolean;
      disabled?: boolean;
      loading?: boolean;
    };

export interface ModalContextType {
  modals: Record<string, ModalConfig>;
  openModal: (config: ModalConfig) => void;
  closeModal: (id: string) => void;
  closeAllModals: () => void;
  updateModal: (id: string, updates: Partial<ModalConfig>) => void;
}

import { useContext } from 'react';
import { ModalContext } from './context';

export function useModals() {
  const context = useContext(ModalContext);
  if (!context) {
    throw new Error('useModals must be used within a ModalProvider');
  }
  return context;
}

import { createContext, useContext, useEffect, useMemo, useState } from 'react';
import { getCookie, removeCookie, setCookie } from '../lib/cookies';

type Theme = 'dark' | 'light' | 'system';
type ResolvedTheme = Exclude<Theme, 'system'>;

const DEFAULT_THEME = 'light';
const THEME_COOKIE_NAME = 'vite-ui-theme';
const THEME_COOKIE_MAX_AGE = 60 * 60 * 24 * 365; // 1 year

type ThemeProviderProps = {
  children: React.ReactNode;
  defaultTheme?: Theme;
  storageKey?: string;
};

type ThemeProviderState = {
  defaultTheme: Theme;
  resolvedTheme: ResolvedTheme;
  theme: Theme;
  setTheme: (theme: Theme) => void;
  resetTheme: () => void;
};

const initialState: ThemeProviderState = {
  defaultTheme: DEFAULT_THEME,
  resolvedTheme: 'light',
  theme: DEFAULT_THEME,
  setTheme: () => null,
  resetTheme: () => null,
};

const ThemeContext = createContext<ThemeProviderState>(initialState);

export function ThemeProvider({
  children,
  defaultTheme = DEFAULT_THEME,
  storageKey = THEME_COOKIE_NAME,
  ...props
}: ThemeProviderProps) {
  const [theme, _setTheme] = useState<Theme>(
    () => (getCookie(storageKey) as Theme) || defaultTheme
  );

  const resolvedTheme = useMemo((): ResolvedTheme => {
    if (theme === 'system') {
      return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
    }
    return theme as ResolvedTheme;
  }, [theme]);

  useEffect(() => {
    const root = window.document.documentElement;
    const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');

    const applyTheme = (currentResolvedTheme: ResolvedTheme) => {
      root.classList.remove('light', 'dark');
      root.classList.add(currentResolvedTheme);
    };

    const handleChange = () => {
      if (theme === 'system') {
        const systemTheme = mediaQuery.matches ? 'dark' : 'light';
        applyTheme(systemTheme);
      }
    };

    applyTheme(resolvedTheme);
    mediaQuery.addEventListener('change', handleChange);
    return () => mediaQuery.removeEventListener('change', handleChange);
  }, [theme, resolvedTheme]);

  const setTheme = (theme: Theme) => {
    setCookie(storageKey, theme, { maxAge: THEME_COOKIE_MAX_AGE });
    _setTheme(theme);
  };

  const resetTheme = () => {
    removeCookie(storageKey);
    _setTheme(DEFAULT_THEME);
  };

  const contextValue = {
    defaultTheme,
    resolvedTheme,
    resetTheme,
    theme,
    setTheme,
  };

  return (
    <ThemeContext value={contextValue} {...props}>
      {children}
    </ThemeContext>
  );
}

export const useTheme = () => {
  const context = useContext(ThemeContext);
  if (!context) throw new Error('useTheme must be used within a ThemeProvider');
  return context;
};
